import{_ as a,o as s,c as t,a3 as e}from"./chunks/framework.DdpBa4_E.js";const o="/ReadBooks/assets/image-038.CN9C01lC.jpg",i="/ReadBooks/assets/image-091.CVuIm71_.jpg",_="/ReadBooks/assets/image-012.DebI6x4D.jpg",l="/ReadBooks/assets/image-036.D2htKmQ8.jpg",r="/ReadBooks/assets/image-073.DpIHZT4O.jpg",d="/ReadBooks/assets/image-047.CSNGOBdo.jpg",f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/26-团块次代男性中48％是“下流”！.md","filePath":"books/xialiu-shehui/26-团块次代男性中48％是“下流”！.md","lastUpdated":1794732511000}'),n={name:"books/xialiu-shehui/26-团块次代男性中48％是“下流”！.md"};function m(c,p,g,u,h,k){return s(),t("div",null,[...p[0]||(p[0]=[e('<h2 id="团块次代男性中48-是-下流" tabindex="-1">团块次代男性中48%是“下流” <a class="header-anchor" href="#团块次代男性中48-是-下流" aria-label="Permalink to &quot;团块次代男性中48%是“下流”&quot;">​</a></h2><p>笔者曾经做过一个“欲求调查”，从多个方面对昭和初年世代、团块世代、新人类世代以及团块次代四个不同世代进行了对比。本章将根据这一调查的数据，对这四个不同世代的男女阶层意识进行一番比较。</p><p>调查的样本数为居住在首都圈一都三县范围内的800人，其中各个世代的男女各100人。</p><p>关于阶层意识，具体的调查方法是询问被访问者：“你认为自己的生活水平在以下几个等级中属于哪一等？”请他们分别在“上”“中上”“中”“中下”和“下”五个备选答案中选择一个。</p><p>但是一般而言，几乎没有人会认为自己属于“上流”或是“下流”，在内阁府所做的相关调查中，回答“上”和“下”的也分别只有0.7%和6.5%。同样，在上述“欲求调查”中回答“上”的人也只有团块次代的男性、新人类世代的男性、团块世代的女性、昭和初年世代的女性各一名，所占比例仅为1%，而其他世代男性女性的回答数均为零。</p><p>回答“下”的人数分布情况如下：</p><p>团块次代男性　10%</p><p>团块次代女性　4%</p><p>新人类世代男性　8%</p><p>新人类世代女性　6%</p><p>团块世代男性　2%</p><p>团块世代女性　2%</p><p>昭和初年世代男性　5%</p><p>昭和初年世代女性　2%</p><p>在总共800名被访问者中共39名回答“下”，占比例约为5%，与内阁府的调查结果没有太大的差别。</p><p>然而，与团块世代以上人群中认为自己属于“下流”的被访问者只有极少数相对的是，新人类世代以下人群中这一比例却不小，男女合计共有7%，特别是在团块次代的男性中这一比例竟高达10%。由于这个调查是针对消费生活进行的详细调查，因而也有一种可能，即因为团块世代以上的人群对于消费已经变得极为消极，其中的低收入者对此没有给出回答。</p><p>其次，如果我们将“上”与“中上”合并计为“上”，将“中下”与“下”合并计为“下”来进行统计的话，则可以看到，团块次代的男性在各世代男女中的阶层意识最为低下，达到了48%（见表3-1）。这一结果与内阁府于1958年所做的调查结果相近。</p><p>表3-1　各世代男女的阶层意识</p><p><img src="'+o+'" alt="" loading="lazy"></p><p>资料出处：由Culture Studies研究所、e-FALCON共同实施的“欲求调查”</p><p>与此相对，团块次代的女性其阶层意识略高于男性。此外，团块世代女性和新人类世代男性的阶层意识中，“上流”与“中流”之比大约为1:3，这与第一章中提到的201×年等级化社会的模式大体是一致的。根据这一点可以认为，在较年轻的世代中，阶层化即等级的两极分化显然已经开始了。</p><p>不过，在2005年进行的“第一次女性阶层化调查”中，在28—32岁的女性阶层意识中“上”约为10.2%，“下”约为45.4%；33—37岁的女性阶层意识中“上”约为10.6%，“下”约为41.0%，与“欲求调查”的结果相比，自认为属于“下流”的人群数更多（见表3-2）。从提问的内容来分析，应该是“第一次女性阶层化调查”中有更多低收入层的人参加了调查。换句话说，“欲求调查”中30—34岁女性的阶层意识存在一定的偏差，比实际有所提高了。</p><p>表3-2　各年龄层女性的阶层意识</p><p><img src="'+i+'" alt="" loading="lazy"></p><p>资料出处：由Culture Studies研究所、读卖广告社共同实施的“第一次女性阶层化调查”</p><p>此外，由内阁府所做的“国民生活意识调查”中，30—34岁的男性中回答阶层意识“上”的约为8.5%，“中”约为47.2%，“下”约为39.8%，与“欲求调查”的结果无太大的差别。女性则“上”约为8.9%，“中”约为53.8%，“下”约为32.6%。两相比较，“第一次女性阶层化调查”中“下流”的比例更高。</p><p>这里需要指出的是，内阁府的调查样本数为2004年度的30—34岁男性246人、女性325人，“第一次女性阶层化调查”的样本数则要多出许多，故单从统计学上来讲，后者的可信性更加高。另外，“第一次女性阶层化调查”的对象是居住在首都圈一都三县的各年龄层的男性女性，而由此也会带来一定的偏差，即大都市圈内各阶层人群的收入差距很大，加上白领阶层相对较多，而且近年来又不断引入重视成果主义的工资制度，因此收入的差距在不断拉大。</p><p>表3-3　阶层意识的变化——各年龄层的男性</p><p><img src="'+_+'" alt="" loading="lazy"></p><p>（注：20—29岁年龄层的1970—1973年、30岁以上年龄层的1970—1982年各栏因没有每5岁为一段的分段统计，故按照每10岁为一段，将其数值记入表中。）</p><p><img src="'+l+'" alt="" loading="lazy"></p><p>资料出处：内阁府“国民生活意识调查”</p><p>表3-4　阶层意识的变化——各年龄层的女性</p><p><img src="'+r+'" alt="" loading="lazy"></p><p>（注：20—29岁年龄层的1970—1973年、30岁以上年龄层的1970—1982年各栏因没有每5岁为一段的分段统计，故按照每10岁为一段，将其数值记入表中。）</p><p><img src="'+d+'" alt="" loading="lazy"></p><p>资料出处：内阁府“国民生活意识调查”</p><p>最后一点，正如在本书后面还要阐述的，年过30岁而未婚的话会使人的阶层意识跌落，因此，在晚婚比较盛行的大都市圈，“下流”的人数理应增多得更加明显。</p>',38)])])}const B=a(n,[["render",m]]);export{f as __pageData,B as default};
